const char* warp_mma_name(int variant,const megafmm::Problem& p) {
  if(variant==45) {
    if(p.lda%8!=0 || p.ldb%8!=0)return "dense_cublaslt";
    // Only rawA uses TMA; B remains SIMT and has no tensor-map stride bound.
    return p.m%128==0 && p.n%64==0 && p.k%128==0 && uint64_t(p.lda)<(uint64_t(1)<<39) ?
           "megakernel_wgmma_psplit_selective_tma_a_64x32":
           "megakernel_warp_mma_packed";
  }

bool psplit_selective_tma_a_route_enabled() {
  static int cached=-1;
  if(cached>=0)return cached!=0;
  int enabled_dtypes=0,disabled_dtypes=0;
  for(auto dtype:{megafmm::DType::BF16,megafmm::DType::FP16}) {
    auto p=problem(128,64,128,dtype);
    megafmm::Policy policy;policy.algorithm=megafmm::Algorithm::Megakernel;
    policy.mega_variant=45;policy.certified_range=true;policy.workspace_limit=0;
    try {
      auto plan=megafmm::create_plan(p,policy);
      require(plan->algorithm_name()==warp_mma_name(45,p) && plan->workspace_bytes()==0,
              "selective TMA-A45 registered route silently substituted another algorithm");
      ++enabled_dtypes;
    } catch(const std::invalid_argument& e) {
      const std::string message=e.what();
      if(message.find("disabled")==std::string::npos || message.find("45")==std::string::npos)throw;
      ++disabled_dtypes;
    }
  }
  require(enabled_dtypes==2 || disabled_dtypes==2,"selective TMA-A45 enable state differs between dtypes");
  cached=enabled_dtypes==2;
  std::cout << "SELECTIVE_TMA_A_ROUTE_SCOPE variant=45 enabled=" << cached
            << " dtypes=2 metadata_only=1 native_runs=0\n";
  return cached!=0;
}
void psplit_selective_tma_a_blocked_policy_suite() {
  require(!psplit_selective_tma_a_route_enabled(),"selective TMA-A blocked policy requires an explicitly disabled45 route");
  size_t rejected_cases=0,auto_dense_cases=0;
  for(auto dtype:{megafmm::DType::BF16,megafmm::DType::FP16}) {
    megafmm::Policy policy;policy.algorithm=megafmm::Algorithm::Megakernel;
    policy.mega_variant=45;policy.certified_range=true;policy.workspace_limit=0;
    for(int scenario=0;scenario<4;++scenario) {
      auto p=problem(128,64,128,dtype);
      if(scenario==1)p.m=0;if(scenario==2)p.alpha=0;if(scenario==3)p.k=0;
      bool rejected=false;
      try {auto plan=megafmm::create_plan(p,policy);}
      catch(const std::invalid_argument& e) {
        const std::string message=e.what();
        rejected=message.find("disabled")!=std::string::npos && message.find("45")!=std::string::npos;
      }
      require(rejected,"disabled selective TMA-A45 accepted before normal/empty/alpha0/K0 dispatch");
      ++rejected_cases;
    }
    policy.algorithm=megafmm::Algorithm::Auto;
    auto p=problem(128,64,128,dtype);
    require(megafmm::create_plan(p,policy)->algorithm_name()=="dense_cublaslt",
            "Auto selective TMA-A metadata did not retain Dense policy");
    ++auto_dense_cases;
  }
  std::cout << "PASS_WGMMA_PSPLIT_SELECTIVE_TMA_A_BLOCKED_POLICY variant=45 forced_rejections=" << rejected_cases
            << " validate_before_empty_scale=1 auto_dense_dtypes=" << auto_dense_cases << " native_runs=0\n";
}
void psplit_selective_tma_a_stride_metadata_suite() {
  // These shapes have valid finite size_t spans, but are never allocated or run.
  // TMA encode is a launch-only operation; Plan metadata setup cannot encode A.
  constexpr int64_t limit=int64_t(1)<<39;
  size_t cases=0,native_cases=0,packed_cases=0,dense_cases=0;
  for(auto dtype:{megafmm::DType::BF16,megafmm::DType::FP16})
  for(int scenario=0;scenario<5;++scenario) {
    auto p=problem(128,64,128,dtype);
    if(scenario==0)p.lda=limit-8;
    if(scenario==1)p.lda=limit;
    if(scenario==2)p.lda=limit+8;
    if(scenario==3)p.lda=limit+1;
    if(scenario==4)p.ldb=limit; // B is SIMT: the A-only bound must not reject B.
    const size_t a_span=(size_t(p.m-1)*size_t(p.lda)+size_t(p.k))*2;
    const size_t b_span=(size_t(p.k-1)*size_t(p.ldb)+size_t(p.n))*2;
    require(a_span<(size_t(1)<<48) && b_span<(size_t(1)<<48),"selective TMA-A metadata span is not safely bounded");
    const bool native=scenario==0 || scenario==4;
    require(megafmm::wgmma_psplit_selective_tma_a_can_implement(p,0)==native,
            "selective TMA-A guard incorrectly handles A-only stride bound or SIMT B");
    const char* expected=warp_mma_name(45,p);
    std::cout << "BEGIN_WGMMA_PSPLIT_SELECTIVE_TMA_A_STRIDE_METADATA dtype=" << megafmm::dtype_name(dtype)
              << " variant=45 scenario=" << scenario << " lda=" << p.lda << " ldb=" << p.ldb
              << " expected=" << expected << " native_guard=" << native
              << " safe_a_span_bytes=" << a_span << " safe_b_span_bytes=" << b_span << " metadata_only=1 native_runs=0" << std::endl;
    megafmm::Policy policy;policy.algorithm=megafmm::Algorithm::Megakernel;
    policy.mega_variant=45;policy.certified_range=true;policy.workspace_limit=0;
    auto plan=megafmm::create_plan(p,policy);
    require(plan->algorithm_name()==expected,"selective TMA-A Plan stride boundary route differs before encode");
    if(native || scenario==1 || scenario==2)require(plan->workspace_bytes()==0,"metadata native/P7 route unexpectedly allocated workspace");
    std::cout << "META_WGMMA_PSPLIT_SELECTIVE_TMA_A_STRIDE_METADATA dtype=" << megafmm::dtype_name(dtype)
              << " variant=45 scenario=" << scenario << " lda=" << p.lda << " ldb=" << p.ldb
              << " actual=" << plan->algorithm_name() << " native_guard=" << native
              << " safe_a_span_bytes=" << a_span << " safe_b_span_bytes=" << b_span
              << " metadata_only=1 allocated_input_bytes=0 tensor_map_encodes=0 native_runs=0\n";
    ++cases;native_cases+=native;packed_cases+=scenario==1 || scenario==2;dense_cases+=scenario==3;
  }
  std::cout << "PASS_WGMMA_PSPLIT_SELECTIVE_TMA_A_STRIDE_METADATA variant=45 cases=" << cases
            << " native_guard_cases=" << native_cases << " packed_guard_cases=" << packed_cases << " dense_guard_cases=" << dense_cases
            << " A_only_limit=549755813888 B_bound_not_applied=1 metadata_only=1 allocated_input_bytes=0 tensor_map_encodes=0 native_runs=0\n";
}
